-- Add the requested calendar to existing home publications and drafts without replacing their content.
UPDATE puck_pages SET
`published` = CASE WHEN published IS NULL OR instr(published, '/images/calendrier-conte-avent.jpg') > 0 THEN published
 WHEN (SELECT fullkey FROM json_tree(puck_pages.published) WHERE type='object' AND json_extract(CASE WHEN type='object' THEN value ELSE '{}' END,'$.type')='Nouveautes' LIMIT 1) IS NOT NULL THEN json_insert(published, (SELECT fullkey FROM json_tree(puck_pages.published) WHERE type='object' AND json_extract(CASE WHEN type='object' THEN value ELSE '{}' END,'$.type')='Nouveautes' LIMIT 1) || '.props.items[#]', json('{"title":"Le Conte de l’Avent","description":"24 bonbons en chocolat.","kicker":"Calendrier de l’Avent","image":"/images/calendrier-conte-avent.jpg","alt":"Le Conte de l’Avent du Parrain Généreux, calendrier et ses 24 cases de chocolats","href":"/boutique","button_label":"Voir la boutique en ligne","image_fit":"contain"}'))
 ELSE json_insert(published, '$.content[#]', json('{"type":"Nouveautes","props":{"id":"calendrier-avent-nouveautes","title":"Nouveautés & découvertes","intro":"","kicker":"À découvrir","items":[{"title":"Le Conte de l’Avent","description":"24 bonbons en chocolat.","kicker":"Calendrier de l’Avent","image":"/images/calendrier-conte-avent.jpg","alt":"Le Conte de l’Avent du Parrain Généreux, calendrier et ses 24 cases de chocolats","href":"/boutique","button_label":"Voir la boutique en ligne","image_fit":"contain"}],"style":{"background":"","color":"","padding":0,"paddingX":0,"margin":0,"radius":0,"maxWidth":1200,"align":"left","font":"inherit","size":18,"gap":24,"width":100,"minHeight":0,"visualHeight":0,"visualBackground":""}}}')) END,
`draft` = CASE WHEN draft IS NULL OR instr(draft, '/images/calendrier-conte-avent.jpg') > 0 THEN draft
 WHEN (SELECT fullkey FROM json_tree(puck_pages.draft) WHERE type='object' AND json_extract(CASE WHEN type='object' THEN value ELSE '{}' END,'$.type')='Nouveautes' LIMIT 1) IS NOT NULL THEN json_insert(draft, (SELECT fullkey FROM json_tree(puck_pages.draft) WHERE type='object' AND json_extract(CASE WHEN type='object' THEN value ELSE '{}' END,'$.type')='Nouveautes' LIMIT 1) || '.props.items[#]', json('{"title":"Le Conte de l’Avent","description":"24 bonbons en chocolat.","kicker":"Calendrier de l’Avent","image":"/images/calendrier-conte-avent.jpg","alt":"Le Conte de l’Avent du Parrain Généreux, calendrier et ses 24 cases de chocolats","href":"/boutique","button_label":"Voir la boutique en ligne","image_fit":"contain"}'))
 ELSE json_insert(draft, '$.content[#]', json('{"type":"Nouveautes","props":{"id":"calendrier-avent-nouveautes","title":"Nouveautés & découvertes","intro":"","kicker":"À découvrir","items":[{"title":"Le Conte de l’Avent","description":"24 bonbons en chocolat.","kicker":"Calendrier de l’Avent","image":"/images/calendrier-conte-avent.jpg","alt":"Le Conte de l’Avent du Parrain Généreux, calendrier et ses 24 cases de chocolats","href":"/boutique","button_label":"Voir la boutique en ligne","image_fit":"contain"}],"style":{"background":"","color":"","padding":0,"paddingX":0,"margin":0,"radius":0,"maxWidth":1200,"align":"left","font":"inherit","size":18,"gap":24,"width":100,"minHeight":0,"visualHeight":0,"visualBackground":""}}}')) END,
version = version + 1
WHERE path='/' AND ((published IS NOT NULL AND instr(published, '/images/calendrier-conte-avent.jpg')=0) OR (draft IS NOT NULL AND instr(draft, '/images/calendrier-conte-avent.jpg')=0));
